import os
import shutil
import zipfile
import re
import subprocess

source_dir = '/root/papers/all/'
base_target_dir = '/root/'

folders = ['LLM', 'trapped_ion_and_qc', 'black_hole', 'DNA', 'music_history']
for f in folders:
    os.makedirs(os.path.join(base_target_dir, f), exist_ok=True)

def get_text(file_path):
    if file_path.endswith('.pdf'):
        try:
            result = subprocess.run(['pdftotext', '-f', '1', '-l', '1', file_path, '-'], 
                                   capture_output=True, text=True, timeout=10)
            return result.stdout.lower()
        except:
            return ""
    elif file_path.endswith('.docx'):
        try:
            with zipfile.ZipFile(file_path, 'r') as z:
                xml_content = z.read('word/document.xml').decode('utf-8')
                return re.sub('<[^>]+>', '', xml_content).lower()
        except:
            return ""
    elif file_path.endswith('.pptx'):
        try:
            with zipfile.ZipFile(file_path, 'r') as z:
                # Check first few slides
                text = ""
                for i in range(1, 4):
                    slide_file = f'ppt/slides/slide{i}.xml'
                    if slide_file in z.namelist():
                        xml_content = z.read(slide_file).decode('utf-8')
                        text += re.sub('<[^>]+>', '', xml_content).lower()
                return text
        except:
            return ""
    return ""

keywords = {
    'LLM': ['large language model', 'llm', 'chatgpt', 'gpt-4', 'transformer', 'wizardcoder', 'pediatricsgpt', 'instruction-tuned', 'foundation model'],
    'trapped_ion_and_qc': ['trapped ion', 'quantum computing', 'quantum simulation', 'ion-photon', 'qubit', 'paul trap', 'quantum interface', 'quantum computer'],
    'black_hole': ['black hole', 'schwarzschild', 'kerr', 'event horizon', 'hawking radiation', 'black-hole'],
    'DNA': ['dna', 'genomic', 'methylation', 'nucleotide', 'gene', 'translocation', 'dna-binding'],
    'music_history': ['music', 'musical', 'composer', 'western classical', 'pop music', 'rap', 'lyrics', 'hip-hop', 'harmony', 'melody']
}

files = os.listdir(source_dir)
for filename in files:
    file_path = os.path.join(source_dir, filename)
    if not os.path.isfile(file_path):
        continue

    text = get_text(file_path)

    found_folder = None

    # Try keywords
    for folder, kw_list in keywords.items():
        if any(kw in text for kw in kw_list):
            found_folder = folder
            break

    # Fallback to file name keywords if text extraction failed or didn't match
    if not found_folder:
        for folder, kw_list in keywords.items():
            if any(kw in filename.lower() for kw in kw_list):
                found_folder = folder
                break

    # Final fallback: last folder as per instruction "so if a file does not fit into any other 4 folders, it should fit into the last one"
    # Actually the instruction says "Each document belongs and only belongs to one subject folder (so if a file does not fit into any other 4 folders, it should fit into the last one)."
    # Wait, "fit into the last one" usually means the 5th one.
    if not found_folder:
        found_folder = 'music_history' # The last one

    shutil.move(file_path, os.path.join(base_target_dir, found_folder, filename))
    print(f"Moved {filename} to {found_folder}")

