                        xml_content = z.read(slide_file).decode('utf-8')
                        text += re.sub('<[^>]+>', '', xml_content).lower()
                return text
        except:
            return ""
    return ""

# Keywords with word boundary support
keywords = {
    'LLM': [r'\bllm\b', r'large language model', r'chatgpt', r'gpt-4', r'\btransformer\b', r'wizardcoder', r'pediatricsgpt', r'instruction-tuned', r'foundation model'],
    'trapped_ion_and_qc': [r'trapped ion', r'quantum computing', r'quantum simulation', r'ion-photon', r'\bqubit\b', r'paul trap', r'quantum interface', r'quantum computer'],
    'black_hole': [r'black hole', r'schwarzschild', r'kerr', r'event horizon', r'hawking radiation', r'black-hole'],
    'DNA': [r'\bdna\b', r'genomic', r'methylation', r'nucleotide', r'\bgene\b', r'translocation', r'dna-binding'],
    'music_history': [r'music', r'musical', r'composer', r'western classical', r'pop music', r'\brap\b', r'lyrics', r'hip-hop', r'harmony', r'melody', r'vocal']
}

files = os.listdir(source_dir)
for filename in files:
    file_path = os.path.join(source_dir, filename)
    if not os.path.isfile(file_path):
        continue

    text = get_text(file_path)

    scores = {folder: 0 for folder in folders}

    # Try keywords with regex and count matches
    for folder, kw_list in keywords.items():
        for kw in kw_list:
            matches = re.findall(kw, text, re.IGNORECASE)
            scores[folder] += len(matches)

    # Extra weight for title matches (first 200 chars)
    title_part = text[:200]
    for folder, kw_list in keywords.items():
        for kw in kw_list:
            if re.search(kw, title_part, re.IGNORECASE):
                scores[folder] += 5 # Bonus for title match

    # Check filename
    for folder, kw_list in keywords.items():
        for kw in kw_list:
            clean_kw = kw.replace(r'\b', '')
            if re.search(clean_kw, filename, re.IGNORECASE):
                scores[folder] += 10 # Strong bonus for filename match

    best_folder = max(scores, key=scores.get)

    # If no matches at all, use the instruction's fallback (the last one)
    if scores[best_folder] == 0:
        best_folder = 'music_history'

    shutil.move(file_path, os.path.join(base_target_dir, best_folder, filename))
    print(f"Moved {filename} to {best_folder} (Score: {scores})")
